const results = [];
const inputData = $input.all()[0]?.json;
const leads = Array.isArray(inputData?.data) ? inputData.data : [];

// Helper to check title matching
function clean(str) {
  return (str || '').toLowerCase().trim();
}

const indianCities = ['mumbai', 'delhi', 'gurgaon', 'gurugram', 'bangalore', 'bengaluru', 'chennai', 'pune', 'hyderabad', 'kolkata', 'ahmedabad', 'noida'];

for (const lead of leads) {
  const headline = clean(lead.headline);
  const location = clean(lead.location);
  const firstName = lead.firstName || lead.fullName?.split(' ')[0] || '';

  // Must be restricted to India
  const isIndia = location.includes('india') || indianCities.some(city => location.includes(city));
  if (!isIndia) {
    continue; // Skip lead if it's not in India
  }

  let category = null;
  let templateType = Math.random() < 0.5 ? 1 : 2; // Alternating templates randomly
  let draftMessage = '';

  // 1. Check for Category 1: CIO, Fund Manager, Portfolio Manager in specific cities
  const isCat1Title = headline.includes('chief investment officer') ||
                      /\bcio\b/i.test(headline) ||
                      headline.includes('equity fund manager') ||
                      headline.includes('equity portfolio manager');

  const isCat1Location = ['mumbai', 'delhi', 'gurgaon', 'gurugram', 'bangalore', 'bengaluru', 'chennai', 'pune'].some(city => location.includes(city));

  if (isCat1Title && isCat1Location) {
    category = 'CAT-1';
    if (templateType === 1) {
      draftMessage = `Hi ${firstName}, I work in institutional equity research — always looking to connect with fund managers and investment professionals who track Indian equities seriously. No pitch, just building a quality network.`;
    } else {
      draftMessage = `Hi ${firstName}, I work in equity research — covering mid and smallcap ideas — always looking to connect with portfolio managers who follow this space closely. No pitch, just building a quality network.`;
    }
  } 

  // 2. Check for Category 3 first (so AVP / Assistant Vice President doesn't get caught by VP checks)
  else if (
    headline.includes('assistant vice president') ||
    /\bavp\b/i.test(headline) ||
    (headline.includes('president') && !headline.includes('vice president') && !headline.includes('vp'))
  ) {
    category = 'CAT-3';
    if (templateType === 1) {
      draftMessage = `Hi ${firstName}, I work in institutional equity research — always looking to connect with finance and business professionals who are serious about markets and long-term investing. No pitch, just building a quality network.`;
    } else {
      draftMessage = `Hi ${firstName}, I work in equity research with a focus on high-conviction mid and smallcap ideas — always looking to connect with driven professionals who follow Indian markets closely. No pitch, just building a quality network.`;
    }
  }

  // 3. Check for Category 2: CFO, CEO, CMO, VP
  else if (
    headline.includes('chief financial officer') || /\bcfo\b/i.test(headline) ||
    headline.includes('chief executive officer') || /\bceo\b/i.test(headline) ||
    headline.includes('chief marketing officer') || /\bcmo\b/i.test(headline) ||
    headline.includes('vice president') || /\bvp\b/i.test(headline)
  ) {
    category = 'CAT-2';
    if (templateType === 1) {
      draftMessage = `Hi ${firstName}, I work in institutional equity research — always looking to connect with senior leaders and executives who think seriously about capital allocation and wealth creation. No pitch, just building a quality network.`;
    } else {
      draftMessage = `Hi ${firstName}, I work in equity research focused on wealth creation — always looking to connect with CxOs and senior professionals who are building long-term financial depth alongside their careers. No pitch, just building a quality network.`;
    }
  }

  if (category) {
    results.push({
      json: {
        ...lead,
        category,
        draftMessage,
        dateAdded: new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' }).replace(/ /g, '-')
      }
    });
  }
}

return results;
